INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a6a7b9a-482e-5efe-9945-0799d5dc8aa0', 'IIRC Statement of Common Principles of Materiality of the', 'Statement of Common Principles of Materiality of the Corporate Reporting Dialogue', 'The Corporate Reporting Dialogue is designed to respond to market calls for greater coherence, consistency and comparability between corporate reporting frameworks, standards and related requirements.', 'The Corporate Reporting Dialogue is designed to respond to market calls for greater coherence, consistency and comparability between corporate reporting frameworks, standards and related requirements.', 'The Corporate Reporting Dialogue is designed to respond to market calls for greater coherence, consistency and comparability between corporate reporting frameworks, standards and related requirements.', 'IIRC', 'climate', 'in_force', '2016-01-01'::date, 'Corporate Reporting Dialogue', 'https://dl.icdst.org/pdfs/files4/2e3075a9706302387ee828a4435259c2.pdf', ARRAY['iirc', 'guidance_frameworks', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ba5d964-6f30-5864-97c5-0c5b4251c39f', 'International <IR> Framework', 'International <IR> Framework, 2013', 'The IIRC’s long-term vision is a world in which integrated thinking is embedded within mainstream business practice in the public and private sectors, facilitated by Integrated Reporting (<IR>) as the corporate reporting norm. The cycle of integrated thinking and reporting, resulting in efficient and productive capital allocation, will act as a force for financial stability and sustainability.', 'The IIRC’s long-term vision is a world in which integrated thinking is embedded within mainstream business practice in the public and private sectors, facilitated by Integrated Reporting (<IR>) as the corporate reporting norm. The cycle of integrated thinking and reporting, resulting in efficient and productive capital allocation, will act as a force for financial stability and sustainability.', 'The IIRC’s long-term vision is a world in which integrated thinking is embedded within mainstream business practice in the public and private sectors, facilitated by Integrated Reporting (<IR>) as the corporate reporting norm. The cycle of integrated thinking and reporting, resulting in efficient and productive capital allocation, will act as a force for financial stability and sustainability.', 'IIRC', 'climate', 'in_force', '2013-01-01'::date, 'International Integrated Reporting Council (IIRC)', 'https://www.carrotsandsticks.org/policies/313_1', ARRAY['sdg13', 'voluntary', 'sdg16', 'iirc', 'sdg12', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ab161beb-9b24-5047-b96a-a248c71f8321', 'ILO Tripartite Declaration of Principles concerning Multinational Enterprises', 'Tripartite Declaration of Principles concerning Multinational Enterprises and Social Policy (MNE Declaration) – Fifth Edition (2017)', 'The MNE Declaration provides guidelines for multinational enterprises (MNEs), governments, and workers’ organizations on employment, labor rights, and responsible business practices. It promotes decent work, fair employment, and social justice while aligning corporate behavior with international labor standards, including ILO Conventions and UN Guiding Principles on Business and Human Rights.

Key provisions include:

General Principles:
MNEs must respect national laws, human rights, and ILO labor standards.
Businesses must avoid discrimination, forced labor, and child labor.
Employment Practices:
MNEs should contribute to full, productive, and freely chosen employment.
Companies must prioritize local hiring, skills training, and equal treatment.
Conditions of Work & Social Protection:
Wages and benefits must meet or exceed national industry standards.
Companies must ensure safe working conditions and occupational health protections.
Industrial Relations & Collective Bargaining:
Workers must have the right to unionize and bargain collectively.
MNEs should engage in meaningful consultation with workers’ representatives.
Corporate Social Responsibility (CSR) & Sustainability:
MNEs should support human rights, environmental protection, and fair trade practices.
Transparency in business operations, supply chains, and labor policies is required.
The MNE Declaration aligns multinational businesses with international labor standards, ensuring ethical corporate behavior and sustainable economic growth.', 'The MNE Declaration provides guidelines for multinational enterprises (MNEs), governments, and workers’ organizations on employment, labor rights, and responsible business practices. It promotes decent work, fair employment, and social justice while aligning corporate behavior with international labor standards, including ILO Conventions and UN Guiding Principles on Business and Human Rights.

Key provisions include:

General Principles:
MNEs must respect national laws, human rights, and ILO labor standards.
Businesses must avoid discrimination, forced labor, and child labor.
Employment Practices:
MNEs should contribute to full, productive, and freely chosen employment.
Companies must prioritize local hiring, skills training, and equal treatment.
Conditions of Work & Social Protection:
Wages and benefits must meet or exceed national industry standards.
Companies must ensure safe working conditions and occupational health protections.
Industrial Relations & Collective Bargaining:
Workers must have the right to unionize and bargain collectively.
MNEs should engage in meaningful consultation with workers’ representatives.
Corporate Social Responsibility (CSR) & Sustainability:
MNEs should support human rights, environmental protection, and fair trade practices.
Transparency in business operations, supply chains, and labor policies is required.
The MNE Declaration aligns multinational businesses with international labor standards, ensuring ethical corporate behavior and sustainable economic growth.', 'The MNE Declaration provides guidelines for multinational enterprises (MNEs), governments, and workers’ organizations on employment, labor rights, and responsible business practices. It promotes decent work, fair employment, and social justice while aligning corporate behavior with international labor standards, including ILO Conventions and UN Guiding Principles on Business and Human Rights.

Key provisions include:

General Principles:
MNEs must respect national laws, human rights, and ILO labor standards.
Businesses must avoid discrimination, forced labor, and child labor.
Employment Practices:
MNEs should contribute to full, productive, and freely chosen employment.
