INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e0b84850-412f-513e-98be-98063e391081', 'Iraq Corporate Governance Guide for Banks', 'Corporate Governance Guide for Banks 2018', 'This guide is comprised of six (6) sections; the first is the Guide General Framework, the Second is the Board Composition, the Third is the Shariah Board, the Fourth is the Committees, the Fifth is the Bank Executive Management and the Sixth is the Main Structures to achieve Control, Transparency and Disclosure.', 'This guide is comprised of six (6) sections; the first is the Guide General Framework, the Second is the Board Composition, the Third is the Shariah Board, the Fourth is the Committees, the Fifth is the Bank Executive Management and the Sixth is the Main Structures to achieve Control, Transparency and Disclosure.', 'This guide is comprised of six (6) sections; the first is the Guide General Framework, the Second is the Board Composition, the Third is the Shariah Board, the Fourth is the Committees, the Fifth is the Bank Executive Management and the Sixth is the Main Structures to achieve Control, Transparency and Disclosure.', 'Iraq', 'governance', 'in_force', '2018-01-01'::date, 'Iraq', 'https://www.carrotsandsticks.org/policies/81_1', ARRAY['iraq', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('afd8de0b-a98b-5eac-9465-18b7039adfa1', 'Ireland Why nature matters to accountants- A guide', 'Why nature matters to accountants- A guide to building resilience and value through nature-positive action', 'Title: "Why nature matters to accountants- A guide to building resilience and value through nature-positive action" aims to equip accountants with knowledge and practical steps to integrate nature into their work. It targets accountants in various roles, providing guidance on understanding nature''s importance, risks, and opportunities for organizations.', 'Title: "Why nature matters to accountants- A guide to building resilience and value through nature-positive action" aims to equip accountants with knowledge and practical steps to integrate nature into their work. It targets accountants in various roles, providing guidance on understanding nature''s importance, risks, and opportunities for organizations.', 'Title: "Why nature matters to accountants- A guide to building resilience and value through nature-positive action" aims to equip accountants with knowledge and practical steps to integrate nature into their work. It targets accountants in various roles, providing guidance on understanding nature''s importance, risks, and opportunities for organizations.', 'Ireland', 'climate', 'in_force', '2025-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_52', ARRAY['ireland', 'sdg15', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('204ad9a8-d85a-5472-bbdc-f33c998a5a78', 'Ireland S.I. of', 'S.I. No. 309 of 2025', 'The European Union (Corporate Sustainability Reporting) Regulations 2025, issued by the Minister for Enterprise, Tourism and Employment in Ireland, amend previous regulations to align with EU directives on corporate sustainability reporting. The regulations set new implementation dates for reporting requirements, specifically for large companies and their subsidiaries, and clarify definitions related to corporate turnover and applicable entities. These regulations are mandatory for applicable companies, ensuring compliance with EU sustainability standards.', 'The European Union (Corporate Sustainability Reporting) Regulations 2025, issued by the Minister for Enterprise, Tourism and Employment in Ireland, amend previous regulations to align with EU directives on corporate sustainability reporting. The regulations set new implementation dates for reporting requirements, specifically for large companies and their subsidiaries, and clarify definitions related to corporate turnover and applicable entities. These regulations are mandatory for applicable companies, ensuring compliance with EU sustainability standards.', 'The European Union (Corporate Sustainability Reporting) Regulations 2025, issued by the Minister for Enterprise, Tourism and Employment in Ireland, amend previous regulations to align with EU directives on corporate sustainability reporting. The regulations set new implementation dates for reporting requirements, specifically for large companies and their subsidiaries, and clarify definitions related to corporate turnover and applicable entities. These regulations are mandatory for applicable companies, ensuring compliance with EU sustainability standards.', 'Ireland', 'climate', 'in_force', '2025-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_54', ARRAY['sdg8', 'regulations', 'mandatory', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('82a25d01-a49f-5eb7-900a-36a5bae94765', 'Ireland General Scheme of the Equality (Miscellaneous Provisions) Bill', 'General Scheme of the Equality (Miscellaneous Provisions) Bill 2024', 'The General Scheme of the Equality (Miscellaneous Provisions) Bill 2024 in Ireland aims to amend existing equality legislation, including Employment Equality and Equal Status Acts, to enhance protection against discrimination in employment and public services. Key changes include pay transparency, victimization provisions, and extending time limits for redress. Targeted at employers, employees, and service providers.', 'The General Scheme of the Equality (Miscellaneous Provisions) Bill 2024 in Ireland aims to amend existing equality legislation, including Employment Equality and Equal Status Acts, to enhance protection against discrimination in employment and public services. Key changes include pay transparency, victimization provisions, and extending time limits for redress. Targeted at employers, employees, and service providers.', 'The General Scheme of the Equality (Miscellaneous Provisions) Bill 2024 in Ireland aims to amend existing equality legislation, including Employment Equality and Equal Status Acts, to enhance protection against discrimination in employment and public services. Key changes include pay transparency, victimization provisions, and extending time limits for redress. Targeted at employers, employees, and service providers.', 'Ireland', 'nature', 'in_force', '2024-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_49', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'sdg16', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f4e504d0-4240-50a4-8a60-c7ccd512350f', 'Ireland S.I. - European Union (Corporate Sustainability Reporting) Regulations', 'S.I. No. 336/2024 - European Union (Corporate Sustainability Reporting) Regulations 2024', 'S.I. No. 336/2024 - European Union (Corporate Sustainability Reporting) Regulations 2024 in Ireland implements EU Directive 2022/2464, amending reporting regulations for corporate sustainability. Key requirements include changes to the Companies Act 2014. This policy targets companies subject to sustainability reporting obligations.', 'S.I. No. 336/2024 - European Union (Corporate Sustainability Reporting) Regulations 2024 in Ireland implements EU Directive 2022/2464, amending reporting regulations for corporate sustainability. Key requirements include changes to the Companies Act 2014. This policy targets companies subject to sustainability reporting obligations.', 'S.I. No. 336/2024 - European Union (Corporate Sustainability Reporting) Regulations 2024 in Ireland implements EU Directive 2022/2464, amending reporting regulations for corporate sustainability. Key requirements include changes to the Companies Act 2014. This policy targets companies subject to sustainability reporting obligations.', 'Ireland', 'climate', 'in_force', '2024-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_51', ARRAY['ireland', 'sdg15', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('342e449f-fb64-51c6-94e3-401ade642af3', 'Ireland S.I', 'S.I. No. 498/2024', 'The European Union (Corporate Sustainability Reporting) (No. 2) Regulations 2024 aim to enhance corporate sustainability reporting in Ireland by amending existing regulations under the Companies Act 2014. The regulations are designed to implement Directive (EU) 2022/2464, which updates previous directives on corporate reporting. They specifically apply to public-interest entities and amend certain sections of the Companies Act to clarify reporting obligations. The regulations are mandatory for applicable companies as defined within the legislation.', 'The European Union (Corporate Sustainability Reporting) (No. 2) Regulations 2024 aim to enhance corporate sustainability reporting in Ireland by amending existing regulations under the Companies Act 2014. The regulations are designed to implement Directive (EU) 2022/2464, which updates previous directives on corporate reporting. They specifically apply to public-interest entities and amend certain sections of the Companies Act to clarify reporting obligations. The regulations are mandatory for applicable companies as defined within the legislation.', 'The European Union (Corporate Sustainability Reporting) (No. 2) Regulations 2024 aim to enhance corporate sustainability reporting in Ireland by amending existing regulations under the Companies Act 2014. The regulations are designed to implement Directive (EU) 2022/2464, which updates previous directives on corporate reporting. They specifically apply to public-interest entities and amend certain sections of the Companies Act to clarify reporting obligations. The regulations are mandatory for applicable companies as defined within the legislation.', 'Ireland', 'climate', 'in_force', '2024-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_53', ARRAY['regulations', 'mandatory', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
