INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3ca6b41-6cdd-5d41-a017-1b83079cd533', 'Ireland Irish Green Public Procurement Criteria: ICT products and', 'Irish Green Public Procurement Criteria: ICT products and services 2022', 'This document sets out the core and comprehensive GPP criteria for the purchase of Information and Communications Technology (ICT) products and services by Irish public bodies.', 'This document sets out the core and comprehensive GPP criteria for the purchase of Information and Communications Technology (ICT) products and services by Irish public bodies.', 'This document sets out the core and comprehensive GPP criteria for the purchase of Information and Communications Technology (ICT) products and services by Irish public bodies.', 'Ireland', 'nature', 'in_force', '2022-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_48', ARRAY['mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fdb8b4df-bfde-589f-a70a-eba1a31c826d', 'Ireland Climate Action and Low Carbon Development (Amendment) Act', 'Climate Action and Low Carbon Development (Amendment) Act 2021', 'The Climate Action and Low Carbon Development (Amendment) Act 2021 has been signed into law committing Ireland to 2030 and 2050 targets for reducing greenhouse gas (GHG) emissions and providing the governance framework. The country is now on a legally binding path to net-zero emissions no later than 2050, and to a 51% reduction in emissions by the end of this decade. The Climate Action Plan 2021 will be published in early autumn and will set out the measures to be taken to reach national climate targets in each sector of the economy.', 'The Climate Action and Low Carbon Development (Amendment) Act 2021 has been signed into law committing Ireland to 2030 and 2050 targets for reducing greenhouse gas (GHG) emissions and providing the governance framework. The country is now on a legally binding path to net-zero emissions no later than 2050, and to a 51% reduction in emissions by the end of this decade. The Climate Action Plan 2021 will be published in early autumn and will set out the measures to be taken to reach national climate targets in each sector of the economy.', 'The Climate Action and Low Carbon Development (Amendment) Act 2021 has been signed into law committing Ireland to 2030 and 2050 targets for reducing greenhouse gas (GHG) emissions and providing the governance framework. The country is now on a legally binding path to net-zero emissions no later than 2050, and to a 51% reduction in emissions by the end of this decade. The Climate Action Plan 2021 will be published in early autumn and will set out the measures to be taken to reach national climate targets in each sector of the economy.', 'Ireland', 'climate', 'in_force', '2021-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_16', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg15', 'ireland', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2bc1f486-ea20-515b-8e49-2e9972665c4c', 'Ireland Green Public Procurement. Guidance for the Public Sector', 'Green Public Procurement. Guidance for the Public Sector', 'Ireland has committed to implementing green public procurement (GPP) in all tenders using public funds by 2023. This will require a major shift in the practices of public bodies and the businesses they contract with. This second edition of the EPA Green Public Procurement Guidance supports this transition.', 'Ireland has committed to implementing green public procurement (GPP) in all tenders using public funds by 2023. This will require a major shift in the practices of public bodies and the businesses they contract with. This second edition of the EPA Green Public Procurement Guidance supports this transition.', 'Ireland has committed to implementing green public procurement (GPP) in all tenders using public funds by 2023. This will require a major shift in the practices of public bodies and the businesses they contract with. This second edition of the EPA Green Public Procurement Guidance supports this transition.', 'Ireland', 'climate', 'in_force', '2021-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_37', ARRAY['guidance_frameworks', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d008a14b-da43-5278-b886-eef2574407de', 'Ireland Business and Human Rights Guidance for business enterprises', 'Business and Human Rights Guidance for business enterprises', 'Launched in 2021, Ireland''s "Business & Human Rights Guidance" empowers businesses to respect human rights throughout their operations and supply chains. Aligning with UN principles, it outlines practical steps for identifying, preventing, and mitigating potential human rights impacts across a range of areas like labor, environment, and indigenous rights. By encouraging due diligence, reporting, and stakeholder engagement, it promotes responsible business practices that contribute to a more just and sustainable future.', 'Launched in 2021, Ireland''s "Business & Human Rights Guidance" empowers businesses to respect human rights throughout their operations and supply chains. Aligning with UN principles, it outlines practical steps for identifying, preventing, and mitigating potential human rights impacts across a range of areas like labor, environment, and indigenous rights. By encouraging due diligence, reporting, and stakeholder engagement, it promotes responsible business practices that contribute to a more just and sustainable future.', 'Launched in 2021, Ireland''s "Business & Human Rights Guidance" empowers businesses to respect human rights throughout their operations and supply chains. Aligning with UN principles, it outlines practical steps for identifying, preventing, and mitigating potential human rights impacts across a range of areas like labor, environment, and indigenous rights. By encouraging due diligence, reporting, and stakeholder engagement, it promotes responsible business practices that contribute to a more just and sustainable future.', 'Ireland', 'climate', 'in_force', '2021-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_38', ARRAY['guidance_frameworks', 'sdg17', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5d85975a-fdb1-50d5-b4aa-3c9c64825e39', 'Ireland Irish Corporate Governance Annex', 'The Irish Corporate Governance Annex 2019', 'The Irish Corporate Governance Annex (the ‘Irish Annex’) is addressed to companies with a primary equity listing on Euronext Dublin. The Irish  Annex implements the nine recommendations arising from the report commissioned by Euronext Dublin and IAIM in early 2010.', 'The Irish Corporate Governance Annex (the ‘Irish Annex’) is addressed to companies with a primary equity listing on Euronext Dublin. The Irish  Annex implements the nine recommendations arising from the report commissioned by Euronext Dublin and IAIM in early 2010.', 'The Irish Corporate Governance Annex (the ‘Irish Annex’) is addressed to companies with a primary equity listing on Euronext Dublin. The Irish  Annex implements the nine recommendations arising from the report commissioned by Euronext Dublin and IAIM in early 2010.', 'Ireland', 'climate', 'in_force', '2019-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_2', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'ireland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6051595e-d0ab-50f1-9c28-eec61d254882', 'Toward Responsible Business - Ireland''s National Plan', 'Toward Responsible Business - Ireland''s National Plan on Corporate Social Responsibility 2017 – 2020', 'The National Plan aims to build on the achievements of the first National Plan on CSR 2014—2016 and to further support businesses in Ireland to create sustainable jobs; embed responsible practices in the marketplace; embrace diversity and promote responsible workplaces; and encourage enterprises to consider their businesses’ impacts on the environment. It also aims to align its goals with Government’s objective, outlined in the ‘Programme for a Partnership Government’, of achieving ‘a fair society based on a strong economy’.', 'The National Plan aims to build on the achievements of the first National Plan on CSR 2014—2016 and to further support businesses in Ireland to create sustainable jobs; embed responsible practices in the marketplace; embrace diversity and promote responsible workplaces; and encourage enterprises to consider their businesses’ impacts on the environment. It also aims to align its goals with Government’s objective, outlined in the ‘Programme for a Partnership Government’, of achieving ‘a fair society based on a strong economy’.', 'The National Plan aims to build on the achievements of the first National Plan on CSR 2014—2016 and to further support businesses in Ireland to create sustainable jobs; embed responsible practices in the marketplace; embrace diversity and promote responsible workplaces; and encourage enterprises to consider their businesses’ impacts on the environment. It also aims to align its goals with Government’s objective, outlined in the ‘Programme for a Partnership Government’, of achieving ‘a fair society based on a strong economy’.', 'Ireland', 'climate', 'in_force', '2017-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_14', ARRAY['other sustainability policy', 'sdg17', 'mandatory', 'mandatory_regulations', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e62aabfe-19cb-5cda-ae8b-bda9fc8ce1a9', 'Ireland National Plan on Business and Human Rights 2017', 'National Plan on Business and Human Rights 2017 - 2020', 'This National Plan has been developed on foot of a government decision in June 2014, following an extensive consultation process. It aims to promote responsible business practice at home and overseas.', 'This National Plan has been developed on foot of a government decision in June 2014, following an extensive consultation process. It aims to promote responsible business practice at home and overseas.', 'This National Plan has been developed on foot of a government decision in June 2014, following an extensive consultation process. It aims to promote responsible business practice at home and overseas.', 'Ireland', 'climate', 'in_force', '2017-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_18', ARRAY['sdg14', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'ireland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b943e186-d7d2-5238-8d75-7f07eb71f048', 'Ireland Code of Practice for Good Governance of Community', 'Code of Practice for Good Governance of Community, Voluntary and Charitable Organisations in Ireland 2016', 'This Governance Code is a voluntary code of practice for good governance of Community, Voluntary and Charitable (CVC) organisations in Ireland. As the Code has been developed for and by the CVC sector, it offers your organisation a lot of room to decide how it should act while following the principles of good governance.', 'This Governance Code is a voluntary code of practice for good governance of Community, Voluntary and Charitable (CVC) organisations in Ireland. As the Code has been developed for and by the CVC sector, it offers your organisation a lot of room to decide how it should act while following the principles of good governance.', 'This Governance Code is a voluntary code of practice for good governance of Community, Voluntary and Charitable (CVC) organisations in Ireland. As the Code has been developed for and by the CVC sector, it offers your organisation a lot of room to decide how it should act while following the principles of good governance.', 'Ireland', 'nature', 'in_force', '2016-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_3', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'sdg16', 'ireland', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
