INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4deea701-384c-5b20-92b8-a3af6b84c888', 'Ireland Corporate Governance Requirements for Insurance Undertakings', 'Corporate Governance Requirements for Insurance Undertakings 2015', 'The Corporate Governance Requirements for Insurance Undertakings 2015 (‘the Requirements’) set out the corporate governance obligations which apply to insurance undertakings, excluding captive insurance and captive reinsurance undertakings, with effect from  1 January 2015.', 'The Corporate Governance Requirements for Insurance Undertakings 2015 (‘the Requirements’) set out the corporate governance obligations which apply to insurance undertakings, excluding captive insurance and captive reinsurance undertakings, with effect from  1 January 2015.', 'The Corporate Governance Requirements for Insurance Undertakings 2015 (‘the Requirements’) set out the corporate governance obligations which apply to insurance undertakings, excluding captive insurance and captive reinsurance undertakings, with effect from  1 January 2015.', 'Ireland', 'nature', 'in_force', '2015-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_11', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('90fabfa6-aa6e-5171-8ac8-a0ae9e1f71a2', 'Ireland Petroleum Safety Act', 'Petroleum Safety Act', 'An Act to give effect to Directive 2013/30/EU of the European Parliament and of the Council of 12 June 20131 and for that purpose to amend the Petroleum and Other Minerals Development Act 1960, section 6 of the Continental Shelf Act 1968 and the Electricity Regulation Act 1999 and to provide for related matters.', 'An Act to give effect to Directive 2013/30/EU of the European Parliament and of the Council of 12 June 20131 and for that purpose to amend the Petroleum and Other Minerals Development Act 1960, section 6 of the Continental Shelf Act 1968 and the Electricity Regulation Act 1999 and to provide for related matters.', 'An Act to give effect to Directive 2013/30/EU of the European Parliament and of the Council of 12 June 20131 and for that purpose to amend the Petroleum and Other Minerals Development Act 1960, section 6 of the Continental Shelf Act 1968 and the Electricity Regulation Act 1999 and to provide for related matters.', 'Ireland', 'climate', 'in_force', '2015-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_29', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'ireland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41c28480-b745-506b-bc63-b9938dfc4cf7', 'Ireland S.I. - European Union (Energy Efficiency) Regulations', 'S.I. No. 426/2014 - European Union (Energy Efficiency) Regulations 2014', 'The European Union (Energy Efficiency) Regulations 2014 in Ireland aim to enforce energy efficiency measures across various sectors. The policy outlines obligations for public bodies, energy audits, metering and billing, combined heat and power, energy transformation, information services, incentives, and financing. It requires compliance with energy efficiency standards, penalties for non-compliance, and promotion of efficiency in heating, cooling, and energy distribution. The policy targets enhancing energy efficiency in the public sector, regulated and non-regulated energy sectors, and aims to provide information, training, and financing for energy efficiency improvements.', 'The European Union (Energy Efficiency) Regulations 2014 in Ireland aim to enforce energy efficiency measures across various sectors. The policy outlines obligations for public bodies, energy audits, metering and billing, combined heat and power, energy transformation, information services, incentives, and financing. It requires compliance with energy efficiency standards, penalties for non-compliance, and promotion of efficiency in heating, cooling, and energy distribution. The policy targets enhancing energy efficiency in the public sector, regulated and non-regulated energy sectors, and aims to provide information, training, and financing for energy efficiency improvements.', 'The European Union (Energy Efficiency) Regulations 2014 in Ireland aim to enforce energy efficiency measures across various sectors. The policy outlines obligations for public bodies, energy audits, metering and billing, combined heat and power, energy transformation, information services, incentives, and financing. It requires compliance with energy efficiency standards, penalties for non-compliance, and promotion of efficiency in heating, cooling, and energy distribution. The policy targets enhancing energy efficiency in the public sector, regulated and non-regulated energy sectors, and aims to provide information, training, and financing for energy efficiency improvements.', 'Ireland', 'climate', 'in_force', '2014-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_1', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6cb57f3b-76fc-53a0-b4ba-eaeedd203e28', 'Ireland S.I. of 2014 – European Union (Energy Efficiency', 'S.I. No. 131 of 2014 – European Union (Energy Efficiency Obligation Scheme) Regulations', 'These Regulations require: (a) energy distributors, (b) distribution system operators, and (c) retail energy sales companies, to comply with an Energy Efficiency Notices issued on the basis of the Energy Efficiency Obligation Scheme established and administered by the Minister for Communications, Energy and Natural Resources. The Energy Efficiency Notice to an energy supplier or class of energy suppliers shall set out the measures, standards, conditions, thresholds, timescales and targets to be.', 'These Regulations require: (a) energy distributors, (b) distribution system operators, and (c) retail energy sales companies, to comply with an Energy Efficiency Notices issued on the basis of the Energy Efficiency Obligation Scheme established and administered by the Minister for Communications, Energy and Natural Resources. The Energy Efficiency Notice to an energy supplier or class of energy suppliers shall set out the measures, standards, conditions, thresholds, timescales and targets to be.', 'These Regulations require: (a) energy distributors, (b) distribution system operators, and (c) retail energy sales companies, to comply with an Energy Efficiency Notices issued on the basis of the Energy Efficiency Obligation Scheme established and administered by the Minister for Communications, Energy and Natural Resources. The Energy Efficiency Notice to an energy supplier or class of energy suppliers shall set out the measures, standards, conditions, thresholds, timescales and targets to be.', 'Ireland', 'climate', 'in_force', '2014-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_15', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'ireland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ba090e9f-e57b-5755-b934-63d17e011326', 'Ireland Companies Act', 'Companies Act', 'The Irish Companies Act 2014 contains provisions that promote sustainability and Corporate Social Responsibility (CSR) for companies operating in Ireland. Under Section 158 of the Act, directors of Irish companies are required to consider the long-term consequences of their decisions, including the impact on the environment, the local community, and the company''s stakeholders. This includes the need to balance the interests of shareholders with the interests of other stakeholders such as employees, customers, suppliers, and the wider community. Additionally, the Act requires larger companies to disclose information on their social and environmental impact in their annual reports, including information on their policies, risks, and outcomes related to environmental and social matters, human rights, and anti-corruption. Furthermore, Section 225 of the Act provides for the establishment of a statutory framework for social enterprise, which encourages businesses to operate in a socially responsible and sustainable manner. This includes provisions for companies to register as a social enterprise and to access support and funding from the government. Overall, the Irish Companies Act 2014 aims to promote sustainability and CSR by requiring companies to consider the impact of their actions on the environment and society, to disclose information on their social and environmental impact, and to encourage the establishment of social enterprises.', 'The Irish Companies Act 2014 contains provisions that promote sustainability and Corporate Social Responsibility (CSR) for companies operating in Ireland. Under Section 158 of the Act, directors of Irish companies are required to consider the long-term consequences of their decisions, including the impact on the environment, the local community, and the company''s stakeholders. This includes the need to balance the interests of shareholders with the interests of other stakeholders such as employees, customers, suppliers, and the wider community. Additionally, the Act requires larger companies to disclose information on their social and environmental impact in their annual reports, including information on their policies, risks, and outcomes related to environmental and social matters, human rights, and anti-corruption. Furthermore, Section 225 of the Act provides for the establishment of a statutory framework for social enterprise, which encourages businesses to operate in a socially responsible and sustainable manner. This includes provisions for companies to register as a social enterprise and to access support and funding from the government. Overall, the Irish Companies Act 2014 aims to promote sustainability and CSR by requiring companies to consider the impact of their actions on the environment and society, to disclose information on their social and environmental impact, and to encourage the establishment of social enterprises.', 'The Irish Companies Act 2014 contains provisions that promote sustainability and Corporate Social Responsibility (CSR) for companies operating in Ireland. Under Section 158 of the Act, directors of Irish companies are required to consider the long-term consequences of their decisions, including the impact on the environment, the local community, and the company''s stakeholders. This includes the need to balance the interests of shareholders with the interests of other stakeholders such as employees, customers, suppliers, and the wider community. Additionally, the Act requires larger companies to disclose information on their social and environmental impact in their annual reports, including information on their policies, risks, and outcomes related to environmental and social matters, human rights, and anti-corruption. Furthermore, Section 225 of the Act provides for the establishment of a statutory framework for social enterprise, which encourages businesses to operate in a socially responsible and sustainable manner. This includes provisions for companies to register as a social enterprise and to access support and funding from the government. Overall, the Irish Companies Act 2014 aims to promote sustainability and CSR by requiring companies to consider the impact of their actions on the environment and society, to disclose information on their social and environmental impact, and to encourage the establishment of social enterprises.', 'Ireland', 'climate', 'in_force', '2014-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_23', ARRAY['regulations', 'sdg11', 'mandatory', 'sdg16', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76de62ea-18bb-5e70-9602-758d4a9be306', 'Ireland Corporate Governance Code for Credit Institutions and Insurance', 'Corporate Governance Code for Credit Institutions and Insurance Undertakings 2013', 'The Code imposes the following: Minimum core standards upon all credit institutions and insurance undertakings licensed or authorised by the Central Bank (including reinsurers but excluding captives); and Additional requirements (as set out in Appendix 1) upon institutions which are designated as High Impact by the Central Bank so as to ensure that appropriate and robust corporate governance frameworks are in place and implemented to reflect the risk and nature of those institutions.', 'The Code imposes the following: Minimum core standards upon all credit institutions and insurance undertakings licensed or authorised by the Central Bank (including reinsurers but excluding captives); and Additional requirements (as set out in Appendix 1) upon institutions which are designated as High Impact by the Central Bank so as to ensure that appropriate and robust corporate governance frameworks are in place and implemented to reflect the risk and nature of those institutions.', 'The Code imposes the following: Minimum core standards upon all credit institutions and insurance undertakings licensed or authorised by the Central Bank (including reinsurers but excluding captives); and Additional requirements (as set out in Appendix 1) upon institutions which are designated as High Impact by the Central Bank so as to ensure that appropriate and robust corporate governance frameworks are in place and implemented to reflect the risk and nature of those institutions.', 'Ireland', 'nature', 'in_force', '2013-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_7', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6940d007-aedd-53f2-86b0-20a5bb81d879', 'Ireland Code of Practice for Good Governance of Community', 'A Code of Practice for Good Governance of Community, Voluntary and Charitable Organisations in Ireland 2012', 'The Governance Code clearly outlines the roles, duties and responsibilities of all those who sit on boards and management committees of CVC organisations. It provides, for the first time, a set of guiding principles for governance as well as clear actions that allow those principles to become real within an organisation.', 'The Governance Code clearly outlines the roles, duties and responsibilities of all those who sit on boards and management committees of CVC organisations. It provides, for the first time, a set of guiding principles for governance as well as clear actions that allow those principles to become real within an organisation.', 'The Governance Code clearly outlines the roles, duties and responsibilities of all those who sit on boards and management committees of CVC organisations. It provides, for the first time, a set of guiding principles for governance as well as clear actions that allow those principles to become real within an organisation.', 'Ireland', 'nature', 'in_force', '2012-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_35', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'sdg16', 'ireland', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d168b11b-db4c-5191-a769-4621e7bbd2ff', 'Ireland Corporate Governance Code for Collective Investment Schemes', 'Corporate Governance Code for Collective Investment Schemes and Management Companies 2011', 'The Corporate Governance Code for Collective Investment Schemes and Management Companies in Ireland sets voluntary guidelines effective from January 2012 with a 12-month transition period. It aims to ensure efficient and investor-focused operation of collective investment schemes, recommending governance structures for Irish authorized CIS and Management Companies. Key aspects include defining CIS, outlining governance requirements, specifying roles of boards, promoters, investment managers, administrators, and custodians/trustees. The code emphasizes oversight, expertise, and compliance to promote effective governance within the financial sector.', 'The Corporate Governance Code for Collective Investment Schemes and Management Companies in Ireland sets voluntary guidelines effective from January 2012 with a 12-month transition period. It aims to ensure efficient and investor-focused operation of collective investment schemes, recommending governance structures for Irish authorized CIS and Management Companies. Key aspects include defining CIS, outlining governance requirements, specifying roles of boards, promoters, investment managers, administrators, and custodians/trustees. The code emphasizes oversight, expertise, and compliance to promote effective governance within the financial sector.', 'The Corporate Governance Code for Collective Investment Schemes and Management Companies in Ireland sets voluntary guidelines effective from January 2012 with a 12-month transition period. It aims to ensure efficient and investor-focused operation of collective investment schemes, recommending governance structures for Irish authorized CIS and Management Companies. Key aspects include defining CIS, outlining governance requirements, specifying roles of boards, promoters, investment managers, administrators, and custodians/trustees. The code emphasizes oversight, expertise, and compliance to promote effective governance within the financial sector.', 'Ireland', 'nature', 'in_force', '2011-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_5', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'sdg15', 'disclosure', 'ireland', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d9adebb7-1ddb-5ebd-ab67-dcaf4361163c', 'Ireland Code of Corporate Governance for Independent Directors', 'Code of Corporate Governance for Independent Directors of Investment Funds 2010', 'This Code has been developed as a response to the question frequently asked of CGAI members; namely, “what is best governance practice for Irish investment funds?”. This is a difficult question to answer specifically as little direct legal, regulatory or other guidance exists for investment fund governance in Ireland.', 'This Code has been developed as a response to the question frequently asked of CGAI members; namely, “what is best governance practice for Irish investment funds?”. This is a difficult question to answer specifically as little direct legal, regulatory or other guidance exists for investment fund governance in Ireland.', 'This Code has been developed as a response to the question frequently asked of CGAI members; namely, “what is best governance practice for Irish investment funds?”. This is a difficult question to answer specifically as little direct legal, regulatory or other guidance exists for investment fund governance in Ireland.', 'Ireland', 'nature', 'in_force', '2010-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_4', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a3089421-ff41-536e-849f-232dce87a647', 'Ireland Corporate Governance Code for Credit Institutions and Insurance', 'Corporate Governance Code for Credit Institutions and Insurance Undertakings 2010', 'The Code contains the minimum requirements that an institution shall meet in the interests of promoting strong and effective governance.', 'The Code contains the minimum requirements that an institution shall meet in the interests of promoting strong and effective governance.', 'The Code contains the minimum requirements that an institution shall meet in the interests of promoting strong and effective governance.', 'Ireland', 'nature', 'in_force', '2010-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_6', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ddf9d334-5f15-5d77-841e-25a028f929a2', 'Ireland Corporate Governance Code for Irish Domiciled Collective Investment', 'Corporate Governance Code for Irish Domiciled Collective Investment Schemes 2010', 'This Code is applicable to all Irish domiciled collective investment schemes1 and not just those Irish authorised collective investment schemes admitted to trading on a regulated market.', 'This Code is applicable to all Irish domiciled collective investment schemes1 and not just those Irish authorised collective investment schemes admitted to trading on a regulated market.', 'This Code is applicable to all Irish domiciled collective investment schemes1 and not just those Irish authorised collective investment schemes admitted to trading on a regulated market.', 'Ireland', 'governance', 'in_force', '2010-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_8', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'ireland', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ac7f605a-05ed-57ca-9712-6f970b4f555b', 'Ireland Irish Development NGOs Code of Corporate Governance', 'Irish Development NGOs Code of Corporate Governance 2008', 'Irish Development NGOs exist to create a better world. They operate on a global scale with diverse missions, but are united by a shared commitment to social justice and the eradication of poverty. For all Dóchas members, the principles of participation and transparency are integral to development processes and to the workings of Development NGOs.', 'Irish Development NGOs exist to create a better world. They operate on a global scale with diverse missions, but are united by a shared commitment to social justice and the eradication of poverty. For all Dóchas members, the principles of participation and transparency are integral to development processes and to the workings of Development NGOs.', 'Irish Development NGOs exist to create a better world. They operate on a global scale with diverse missions, but are united by a shared commitment to social justice and the eradication of poverty. For all Dóchas members, the principles of participation and transparency are integral to development processes and to the workings of Development NGOs.', 'Ireland', 'nature', 'in_force', '2008-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_13', ARRAY['guidance_frameworks', 'ireland', 'mandatory', 'sdg16', 'disclosure', 'sdg1', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2d99021-843b-5413-bea8-58c88c9d1d8e', 'Ireland Corporate Governance for Reinsurance Undertakings', 'Corporate Governance for Reinsurance Undertakings 2007', 'As the reinsurance sector in Ireland moves to formal regulation following the publication of Council Directive 2005/68/EC (“Reinsurance Directive”) on the 9th of December 2005, corporate governance standards within reinsurance undertakings will be subject to regulatory oversight. Following transposition of the Reinsurance Directive in Ireland via Statutory Instrument 380 of 2006 (“S.I. 380”), signed into Irish law on the 15th of July 2006, the Irish Financial Services Regulatory Authority (“Financial Regulator”) is issuing this paper to outline to the sector how Corporate Governance will be dealt with in practice between individual reinsurance undertakings and the Financial Regulator.', 'As the reinsurance sector in Ireland moves to formal regulation following the publication of Council Directive 2005/68/EC (“Reinsurance Directive”) on the 9th of December 2005, corporate governance standards within reinsurance undertakings will be subject to regulatory oversight. Following transposition of the Reinsurance Directive in Ireland via Statutory Instrument 380 of 2006 (“S.I. 380”), signed into Irish law on the 15th of July 2006, the Irish Financial Services Regulatory Authority (“Financial Regulator”) is issuing this paper to outline to the sector how Corporate Governance will be dealt with in practice between individual reinsurance undertakings and the Financial Regulator.', 'As the reinsurance sector in Ireland moves to formal regulation following the publication of Council Directive 2005/68/EC (“Reinsurance Directive”) on the 9th of December 2005, corporate governance standards within reinsurance undertakings will be subject to regulatory oversight. Following transposition of the Reinsurance Directive in Ireland via Statutory Instrument 380 of 2006 (“S.I. 380”), signed into Irish law on the 15th of July 2006, the Irish Financial Services Regulatory Authority (“Financial Regulator”) is issuing this paper to outline to the sector how Corporate Governance will be dealt with in practice between individual reinsurance undertakings and the Financial Regulator.', 'Ireland', 'nature', 'in_force', '2007-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_9', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4fc35277-e8e7-5317-81d8-77eb3bb72c76', 'Ireland Safety, Health and Welfare at Work Act', 'Safety, Health and Welfare at Work Act', 'An act to make further provision for securing the safety, health and welfare of persons at work and for the enforcement of the relevant statutory provisions, to give further effect to council directive 89/391/eec of 12 june 19891 on the introduction of measures to encourage improvements in the safety and health of workers at work and council directive 91/383/eec of 25 june 19912 on measures to improve the safety and health at work of workers with a fixed- duration or temporary employment relationship, to provide for the further regulation of work activities, to continue in being and confer additional functions on the national authority for occupational safety and health and rename that body as the health and safety authority, to repeal the safety, health and welfare at work act 1989, to provide for the repeal of certain other enactments and the amendment of the national standards authority of ireland act 1996 and to provide for related matters.', 'An act to make further provision for securing the safety, health and welfare of persons at work and for the enforcement of the relevant statutory provisions, to give further effect to council directive 89/391/eec of 12 june 19891 on the introduction of measures to encourage improvements in the safety and health of workers at work and council directive 91/383/eec of 25 june 19912 on measures to improve the safety and health at work of workers with a fixed- duration or temporary employment relationship, to provide for the further regulation of work activities, to continue in being and confer additional functions on the national authority for occupational safety and health and rename that body as the health and safety authority, to repeal the safety, health and welfare at work act 1989, to provide for the repeal of certain other enactments and the amendment of the national standards authority of ireland act 1996 and to provide for related matters.', 'An act to make further provision for securing the safety, health and welfare of persons at work and for the enforcement of the relevant statutory provisions, to give further effect to council directive 89/391/eec of 12 june 19891 on the introduction of measures to encourage improvements in the safety and health of workers at work and council directive 91/383/eec of 25 june 19912 on measures to improve the safety and health at work of workers with a fixed- duration or temporary employment relationship, to provide for the further regulation of work activities, to continue in being and confer additional functions on the national authority for occupational safety and health and rename that body as the health and safety authority, to repeal the safety, health and welfare at work act 1989, to provide for the repeal of certain other enactments and the amendment of the national standards authority of ireland act 1996 and to provide for related matters.', 'Ireland', 'nature', 'in_force', '2005-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_32', ARRAY['sdg8', 'regulations', 'mandatory', 'disclosure', 'ireland', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ec93d5d-de04-5a5f-a7db-bb07aee1ac83', 'Ireland Corporate Governance, Share Option and Other Incentive Schemes', 'Corporate Governance, Share Option and Other Incentive Schemes 1999', 'The IAIM’s endorsement of the Code extends to its requirements regarding disclosure of directors’ remuneration, the area of single greatest difference between the corporate governance regimes of Ireland and the UK. It is the IAIM’s strong view that, given the increased globalisation of capital markets, trends towards greater accountability and transparency and the need to ensure the optimum attractiveness of Irish stocks in a Euro environment, current disclosure practice in this area is unsustainable. The IAIM recommends that the Combined Code’s requirements regarding disclosure of directors remuneration be adopted in their entirety and that the Irish Stock Exchange should amend its Listing Rules accordingly.', 'The IAIM’s endorsement of the Code extends to its requirements regarding disclosure of directors’ remuneration, the area of single greatest difference between the corporate governance regimes of Ireland and the UK. It is the IAIM’s strong view that, given the increased globalisation of capital markets, trends towards greater accountability and transparency and the need to ensure the optimum attractiveness of Irish stocks in a Euro environment, current disclosure practice in this area is unsustainable. The IAIM recommends that the Combined Code’s requirements regarding disclosure of directors remuneration be adopted in their entirety and that the Irish Stock Exchange should amend its Listing Rules accordingly.', 'The IAIM’s endorsement of the Code extends to its requirements regarding disclosure of directors’ remuneration, the area of single greatest difference between the corporate governance regimes of Ireland and the UK. It is the IAIM’s strong view that, given the increased globalisation of capital markets, trends towards greater accountability and transparency and the need to ensure the optimum attractiveness of Irish stocks in a Euro environment, current disclosure practice in this area is unsustainable. The IAIM recommends that the Combined Code’s requirements regarding disclosure of directors remuneration be adopted in their entirety and that the Irish Stock Exchange should amend its Listing Rules accordingly.', 'Ireland', 'nature', 'in_force', '1999-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_12', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2fc2fcb4-4a6d-5b3e-9fe9-f73e8ba1b9b2', 'Ireland Employment Equality Act', 'Employment Equality Act', 'The Employment Equality Act of 1998 in Ireland aims to prevent discrimination in employment based on gender, age, disability, or other grounds. It outlines obligations for employers, provisions for redress, and the establishment of the Equality Authority to ensure compliance with equality principles. Targeted at employers, employees, and government entities.', 'The Employment Equality Act of 1998 in Ireland aims to prevent discrimination in employment based on gender, age, disability, or other grounds. It outlines obligations for employers, provisions for redress, and the establishment of the Equality Authority to ensure compliance with equality principles. Targeted at employers, employees, and government entities.', 'The Employment Equality Act of 1998 in Ireland aims to prevent discrimination in employment based on gender, age, disability, or other grounds. It outlines obligations for employers, provisions for redress, and the establishment of the Equality Authority to ensure compliance with equality principles. Targeted at employers, employees, and government entities.', 'Ireland', 'nature', 'in_force', '1998-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_50', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'sdg5', 'ireland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('493dd9f0-28b1-5f41-ac11-07adfcd25ab7', 'Ireland Waste Management Act', 'Waste Management Act', 'An act to make provision in relation to the prevention, management and control of waste to give effect to provisions of certain acts adopted by institutions of the European communitie in respect of those matters to amend the environmental protection agency act.', 'An act to make provision in relation to the prevention, management and control of waste to give effect to provisions of certain acts adopted by institutions of the European communitie in respect of those matters to amend the environmental protection agency act.', 'An act to make provision in relation to the prevention, management and control of waste to give effect to provisions of certain acts adopted by institutions of the European communitie in respect of those matters to amend the environmental protection agency act.', 'Ireland', 'circularity', 'in_force', '1996-01-01'::date, 'Ireland', 'https://www.carrotsandsticks.org/policies/82_34', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'ireland']::text[]) ON CONFLICT (id) DO NOTHING;
